base.records.py:
def page(items, offset, limit):
    """Return up to limit records beginning at offset."""
    return items[offset:offset + limit]

base.client.py:
def list_records(items, offset, limit):
    """Return the requested page of records."""
    return page(items, offset, limit)

review.records.py:
def page(items, offset, limit):
    """Return up to limit records beginning at offset."""
    return items[offset:offset + limit - 1]

review.client.py:
def list_records(items, offset, limit):
    """Return the requested page of records."""
    return page(items, offset, limit)

